package stsk8seventsexporter //nolint:testpackage // Drives the exporter's flush directly.

import (
	"context"
	"encoding/json"
	"os"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// testdata/golden.json holds the intake bodies the cluster agent sends for
// testdata/objects.json, generated by testdata/agentgolden/generate.sh. The
// exporter must send the same events. Two envelope differences are expected:
// the agent adds an empty apiKey, and the exporter adds empty topologies,
// health and metrics lists. The agent also writes an empty context.data, which
// the exporter omits.
func TestEventsMatchClusterAgent(t *testing.T) {
	data, err := os.ReadFile("testdata/golden.json")
	require.NoError(t, err)
	var golden map[string]map[string]any
	require.NoError(t, json.Unmarshal(data, &golden))

	for _, clusterType := range []string{clusterTypeKubernetes, clusterTypeOpenShift} {
		t.Run(clusterType, func(t *testing.T) {
			agent := golden[clusterType]
			require.NotNil(t, agent)
			assert.Empty(t, agent["apiKey"])
			delete(agent, "apiKey")
			agentEvents, ok := agent["events"].(map[string]any)
			require.True(t, ok)
			for _, events := range agentEvents {
				dropEmptyContextData(t, events)
			}

			exp, capture := testExporter(t, clusterType, nil)
			consumeFixture(t, exp)
			exp.flush(context.Background())
			_, raw := capture.snapshot()
			require.Len(t, raw, 1)
			body := raw[0]
			for _, list := range []string{"topologies", "health", "metrics"} {
				assert.Equal(t, []any{}, body[list])
				delete(body, list)
			}

			want, err := json.Marshal(agent)
			require.NoError(t, err)
			got, err := json.Marshal(body)
			require.NoError(t, err)
			assert.JSONEq(t, string(want), string(got))
		})
	}
}

func dropEmptyContextData(t *testing.T, events any) {
	t.Helper()
	list, ok := events.([]any)
	require.True(t, ok)
	for _, item := range list {
		event, ok := item.(map[string]any)
		require.True(t, ok)
		eventContext, ok := event["context"].(map[string]any)
		require.True(t, ok)
		assert.Equal(t, map[string]any{}, eventContext["data"])
		delete(eventContext, "data")
	}
}
